// Audio Voice & Chime Engine for Prayer & Meal Attendance
// Guarantees 100% reliable loud pronunciation of 'Hadir' across all browsers & mobile devices

export const ATTENDANCE_AUDIO_BASE64 = {
  hadir: "data:audio/mp3;base64,",
  terlambat: "data:audio/mp3;base64,",
  sakit: "data:audio/mp3;base64,",
  izin: "data:audio/mp3;base64,",
  alpa: "data:audio/mp3;base64,",
  tidak_terdaftar: "data:audio/mp3;base64,",
};

let audioContextInstance: AudioContext | null = null;
let activeUtterance: SpeechSynthesisUtterance | null = null;
let currentAudioElement: HTMLAudioElement | null = null;

// Initialize or resume AudioContext and SpeechSynthesis on user gesture
export function primeAttendanceAudio() {
  try {
    if (typeof window !== 'undefined') {
      const AudioCtx = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      if (AudioCtx && !audioContextInstance) {
        audioContextInstance = new AudioCtx();
      }
      if (audioContextInstance && audioContextInstance.state === 'suspended') {
        audioContextInstance.resume();
      }
      if ('speechSynthesis' in window) {
        window.speechSynthesis.resume();
      }
    }
  } catch {}
}

// Auto unlock audio on any first gesture (click, tap, keypress)
if (typeof window !== 'undefined') {
  const autoUnlock = () => {
    primeAttendanceAudio();
  };
  window.addEventListener('click', autoUnlock, { passive: true });
  window.addEventListener('touchstart', autoUnlock, { passive: true });
  window.addEventListener('keydown', autoUnlock, { passive: true });
}

let lastChimeTime = 0;

// Play loud dual-tone chime
export function playChimeBeep(type: 'success' | 'warning' | 'error' = 'success', enabled: boolean = true) {
  if (!enabled || typeof window === 'undefined') return;
  const nowMs = Date.now();
  if (nowMs - lastChimeTime < 140) return; // Debounce rapid consecutive calls
  lastChimeTime = nowMs;
  try {
    const AudioCtx = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    if (!AudioCtx) return;
    if (!audioContextInstance) audioContextInstance = new AudioCtx();
    if (audioContextInstance.state === 'suspended') audioContextInstance.resume();

    const ctx = audioContextInstance;
    const now = ctx.currentTime;

    if (type === 'success') {
      const osc1 = ctx.createOscillator();
      const osc2 = ctx.createOscillator();
      const gain = ctx.createGain();

      osc1.type = 'triangle';
      osc1.frequency.setValueAtTime(587.33, now); // D5
      osc1.frequency.setValueAtTime(880, now + 0.08); // A5

      osc2.type = 'sine';
      osc2.frequency.setValueAtTime(293.66, now); // D4
      osc2.frequency.setValueAtTime(440, now + 0.08); // A4

      gain.gain.setValueAtTime(0.8, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.35);

      osc1.connect(gain);
      osc2.connect(gain);
      gain.connect(ctx.destination);

      osc1.start(now);
      osc2.start(now);
      osc1.stop(now + 0.35);
      osc2.stop(now + 0.35);
    } else if (type === 'warning') {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(440, now);
      osc.frequency.setValueAtTime(349.23, now + 0.12);
      gain.gain.setValueAtTime(0.7, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.4);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.4);
    } else {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(220, now);
      gain.gain.setValueAtTime(0.8, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.45);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.45);
    }
  } catch {}
}

// Speak student name with Web Speech API after status word
function speakNameWithSpeechSynthesis(name: string) {
  if (typeof window === 'undefined' || !('speechSynthesis' in window) || !name) return;
  try {
    window.speechSynthesis.resume();
    const cleanName = name.trim();
    if (!cleanName || cleanName === '-' || cleanName.toLowerCase().includes('tidak terdaftar')) return;

    const utterance = new SpeechSynthesisUtterance(cleanName);
    utterance.lang = 'id-ID';
    utterance.volume = 1.0;
    utterance.rate = 1.1;
    utterance.pitch = 1.0;

    const voices = window.speechSynthesis.getVoices();
    const idVoice = voices.find(
      (v) =>
        v.lang.toLowerCase().startsWith('id') ||
        v.lang.toLowerCase().includes('indonesia') ||
        v.name.toLowerCase().includes('indonesia')
    );
    if (idVoice) {
      utterance.voice = idVoice;
    }

    // Keep global reference to prevent Chrome GC bug
    activeUtterance = utterance;
    (window as unknown as { __lastUtterance: unknown }).__lastUtterance = utterance;

    utterance.onend = () => {
      activeUtterance = null;
    };
    utterance.onerror = () => {
      activeUtterance = null;
    };

    window.speechSynthesis.speak(utterance);
  } catch {}
}

// Play Voice Status ('Hadir', 'Telat', 'Sakit', 'Izin Pulang', 'Alpa', etc.)
export function playAttendanceVoice(
  status: 'Hadir' | 'Telat' | 'Terlambat' | 'Sakit' | 'Izin Pulang' | 'Alpa' | 'Tidak Terdaftar',
  studentName?: string,
  soundEnabled: boolean = true
) {
  if (!soundEnabled || typeof window === 'undefined') return;

  primeAttendanceAudio();

  // 1. Play high-volume chime
  const chimeType =
    status === 'Hadir' ? 'success' : status === 'Tidak Terdaftar' ? 'error' : 'warning';
  playChimeBeep(chimeType, soundEnabled);

  // 2. Select appropriate audio base64
  let audioKey: keyof typeof ATTENDANCE_AUDIO_BASE64 = 'hadir';
  if (status === 'Telat' || status === 'Terlambat') audioKey = 'terlambat';
  else if (status === 'Sakit') audioKey = 'sakit';
  else if (status === 'Izin Pulang') audioKey = 'izin';
  else if (status === 'Alpa') audioKey = 'alpa';
  else if (status === 'Tidak Terdaftar') audioKey = 'tidak_terdaftar';

  const audioSrc = ATTENDANCE_AUDIO_BASE64[audioKey];
  if (!audioSrc) return;

  try {
    if (currentAudioElement) {
      try {
        currentAudioElement.pause();
        currentAudioElement.currentTime = 0;
      } catch {}
    }

    const audio = new Audio(audioSrc);
    currentAudioElement = audio;
    audio.volume = 1.0; // Maksimal suara

    audio.onended = () => {
      if (studentName && status === 'Hadir') {
        speakNameWithSpeechSynthesis(studentName);
      }
    };

    // Play audio right after the opening chime
    setTimeout(() => {
      const playPromise = audio.play();
      if (playPromise !== undefined) {
        playPromise.catch((err) => {
          console.warn('Audio play prevented by browser autoplay policy, attempting Web Speech fallback:', err);
          // Fallback to Web Speech API directly if HTML audio play is restricted
          if ('speechSynthesis' in window) {
            const fallbackText = status === 'Hadir' ? (studentName ? 'Hadir, ' + studentName : 'Hadir') : status;
            const u = new SpeechSynthesisUtterance(fallbackText);
            u.lang = 'id-ID';
            u.volume = 1.0;
            activeUtterance = u;
            window.speechSynthesis.speak(u);
          }
        });
      }
    }, 160);
  } catch (err) {
    console.warn('Attendance audio error:', err);
  }
}
